1	//! iOS Keychain storage for identity-wallet credentials.
2	//!
3	//! All items are stored as `kSecClassGenericPassword` under
4	//! service `"ezpds-identity-wallet"`. Use the `SERVICE` constant
5	//! to ensure consistency.
6	//!
7	//! # Two stores, not one attribute
8	//!
9	//! The module exposes two families of accessors. `store_item`/`get_item`/`delete_item`
10	//! address the **device-local** store: those items reach a second device by no route the
11	//! wallet uses (iCloud Backup re-encrypts the keychain to the device UID and restores only
12	//! to the same device). `store_item_synced`/`get_item_synced`/`delete_item_synced` address
13	//! the **iCloud-synchronizable** store by setting `kSecAttrSynchronizable`.
14	//!
15	//! These are genuinely different stores, not one item with a flag: Apple's `SecItem.h` is
16	//! explicit that an item is identified by its service + account **and** its synchronizable
17	//! option, and that "if the key is not supplied … no synchronizable items will be added or
18	//! returned." A value written with `store_item` is therefore invisible to `get_item_synced`
19	//! and vice versa. Nothing in `SecItem.h` documents changing an existing item's
20	//! synchronizability, so moving a value between the stores means copying it, never flipping
21	//! it in place.
22	//!
23	//! Accessibility is left at the framework default (`kSecAttrAccessibleWhenUnlocked`) for
24	//! synchronizable items — the `…ThisDeviceOnly` accessibility classes are mutually exclusive
25	//! with syncing.
26	//!
27	//! In test builds (`#[cfg(test)]`), all Keychain operations are redirected to an
28	//! in-memory store so that tests never touch the real macOS Keychain and never
29	//! trigger a password prompt. The test store models the two-store split faithfully —
30	//! the same account in the synced and device-local namespaces is two independent values.
31	
32	#[cfg(not(test))]
33	use security_framework::passwords::{
34	    delete_generic_password, delete_generic_password_options, generic_password,
35	    get_generic_password, set_generic_password, set_generic_password_options, PasswordOptions,
36	};
37	
38	pub const SERVICE: &str = "ezpds-identity-wallet";
39	
40	#[derive(Debug, thiserror::Error)]
41	pub enum KeychainError {
42	    #[error("keychain error: {0}")]
43	    Security(#[from] security_framework::base::Error),
44	    /// A synchronizable-store accessor was called for an account that is not on the
45	    /// iCloud allowlist. Never reachable from the shipped call sites — the guard exists so
46	    /// a future caller cannot quietly widen what leaves the device.
47	    #[error("account {account} is not permitted in the iCloud-synchronizable keychain")]
48	    SyncNotPermitted { account: String },
49	    /// Returned by the in-memory test store when an item is not found.
50	    #[cfg(test)]
51	    #[error("item not found")]
52	    NotFound,
53	}
54	
55	/// Whether `account` is permitted in the **iCloud-synchronizable** Keychain store.
56	///
57	/// A deliberate allowlist of exactly one account family — the per-DID Shamir Share 1 slot
58	/// `recovery-share-1:{did}` — because Share 1 is the only wallet secret whose entire job is
59	/// to survive the loss of the device that created it. Everything else the wallet holds is
60	/// device-local by design, and each exclusion is load-bearing rather than incidental:
61	///
62	/// * **the device key** (`device-rotation-key-*`, `{did}:device-key*`) — on a real device it
63	///   is a Secure Enclave key that *cannot* leave the hardware, and the software fallback must
64	///   not be more portable than the thing it stands in for. It is `rotationKeys[0]`: one
65	///   device, one key, is what makes the 72-hour PLC override meaningful.
66	/// * **`{did}:oauth-tokens`** — a bearer session for one device. Syncing it would put a live
67	///   credential in the Apple account for no recovery benefit; a recovered wallet mints its
68	///   own via sovereign login.
69	/// * **`{did}:recovery-signing-key`** — the self-controlled `atproto` repo signing key. It
70	///   signs commits, so a second live copy is a fork risk, not a backup.
71	/// * **`ceremony-staging` / `recovery-epilogue`** — in-flight ceremony records whose whole
72	///   contract is fail-closed single-device ownership. Two devices resuming one epilogue is a
73	///   correctness hazard, not a convenience: each would drive the same rotation independently
74	///   against a record it believes it owns. They also hold the *seed* (or two shares at once)
75	///   until teardown, so syncing them would place a reconstructable secret in iCloud,
76	///   collapsing the 2-of-3 threshold this whole design exists to hold.
77	///
78	/// Asserted by `deny_list_accounts_never_sync` below.
79	pub fn syncs_to_icloud(account: &str) -> bool {
80	    crate::rekey::is_recovery_share1_account(account)
81	}
82	
83	/// Reject a synchronizable-store call for a non-allowlisted account.
84	fn guard_sync_allowed(account: &str) -> Result<(), KeychainError> {
85	    if syncs_to_icloud(account) {
86	        Ok(())
87	    } else {
88	        Err(KeychainError::SyncNotPermitted {
89	            account: account.to_string(),
90	        })
91	    }
92	}
93	
94	/// Store bytes in the **iCloud-synchronizable** Keychain store.
95	///
96	/// Writes a record distinct from any same-named `store_item` record; it does not migrate,
97	/// replace, or delete the device-local one. Only allowlisted accounts (see
98	/// [`syncs_to_icloud`]) are accepted.
99	///
100	/// A successful return means the item was written carrying `kSecAttrSynchronizable` — **not**
101	/// that it reached the user's Apple account. iOS exposes no delivery callback, and with
102	/// iCloud Keychain switched off the attribute is recorded and propagates nowhere (enabling it
103	/// later syncs the item with no further involvement from this app). User-facing copy must
104	/// claim only the former.
105	pub fn store_item_synced(account: &str, data: &[u8]) -> Result<(), KeychainError> {
106	    guard_sync_allowed(account)?;
107	    #[cfg(test)]
108	    {
109	        test_store::set(test_store::Scope::Synced, account, data.to_vec());
110	        Ok(())
111	    }
112	    #[cfg(not(test))]
113	    set_generic_password_options(data, synced_options(account)).map_err(KeychainError::Security)
114	}
115	
116	/// Retrieve bytes from the **iCloud-synchronizable** Keychain store.
117	///
118	/// Returns `Err` with `errSecItemNotFound` when the synced slot is empty, even if a
119	/// device-local item with the same account exists.
120	pub fn get_item_synced(account: &str) -> Result<Vec<u8>, KeychainError> {
121	    guard_sync_allowed(account)?;
122	    #[cfg(test)]
123	    {
124	        test_store::get(test_store::Scope::Synced, account).ok_or(KeychainError::NotFound)
125	    }
126	    #[cfg(not(test))]
127	    generic_password(synced_options(account)).map_err(KeychainError::Security)
128	}
129	
130	/// Delete an item from the **iCloud-synchronizable** Keychain store, leaving any
131	/// device-local item of the same name untouched.
132	#[cfg_attr(test, allow(dead_code))]
133	pub fn delete_item_synced(account: &str) -> Result<(), KeychainError> {
134	    guard_sync_allowed(account)?;
135	    #[cfg(test)]
136	    {
137	        test_store::delete(test_store::Scope::Synced, account);
138	        Ok(())
139	    }
140	    #[cfg(not(test))]
141	    delete_generic_password_options(synced_options(account)).map_err(KeychainError::Security)
142	}
143	
144	/// Query targeting the synchronizable store for `account`.
145	///
146	/// `Some(true)` (never `None`) so every operation addresses exactly one store: with `None`,
147	/// a set would prefer the device-local store and a get could not say which store answered.
148	#[cfg(not(test))]
149	fn synced_options(account: &str) -> PasswordOptions {
150	    let mut options = PasswordOptions::new_generic_password(SERVICE, account);
151	    options.set_access_synchronized(Some(true));
152	    options
153	}
154	
155	/// Store arbitrary bytes in the **device-local** Keychain store under the given account name.
156	///
157	/// Creates the entry if it doesn't exist, or updates it if it does. The value stays on this
158	/// device; see [`store_item_synced`] for the iCloud-synchronizable store.
159	pub fn store_item(account: &str, data: &[u8]) -> Result<(), KeychainError> {
160	    #[cfg(test)]
161	    {
162	        test_store::set(test_store::Scope::Local, account, data.to_vec());
163	        Ok(())
164	    }
165	    #[cfg(not(test))]
166	    set_generic_password(SERVICE, account, data).map_err(KeychainError::Security)
167	}
168	
169	/// Retrieve bytes from the **device-local** Keychain store for the given account name.
170	///
171	/// Returns `Err` with `errSecItemNotFound` if no entry exists. Never returns a value written
172	/// by [`store_item_synced`].
173	pub fn get_item(account: &str) -> Result<Vec<u8>, KeychainError> {
174	    #[cfg(test)]
175	    {
176	        test_store::get(test_store::Scope::Local, account).ok_or(KeychainError::NotFound)
177	    }
178	    #[cfg(not(test))]
179	    get_generic_password(SERVICE, account).map_err(KeychainError::Security)
180	}
181	
182	/// Delete an item from the **device-local** Keychain store by account name.
183	///
184	/// Returns `Ok(())` on successful deletion, or `Err` if the item doesn't exist.
185	pub fn delete_item(account: &str) -> Result<(), KeychainError> {
186	    #[cfg(test)]
187	    {
188	        test_store::delete(test_store::Scope::Local, account);
189	        Ok(())
190	    }
191	    #[cfg(not(test))]
192	    delete_generic_password(SERVICE, account).map_err(KeychainError::Security)
193	}
194	
195	/// Returns true if the error is errSecItemNotFound (OS status -25300).
196	/// Use this to distinguish "item does not exist" from transient OS errors.
197	pub fn is_not_found(err: &KeychainError) -> bool {
198	    match err {
199	        KeychainError::Security(e) => e.code() == -25300,
200	        // Not an absence claim — the account was never addressed.
201	        KeychainError::SyncNotPermitted { .. } => false,
202	        #[cfg(test)]
203	        KeychainError::NotFound => true,
204	    }
205	}
206	
207	// ── OAuth Keychain helpers ─────────────────────────────────────────────────────
208	
209	const DPOP_KEY_PRIV_ACCOUNT: &str = "oauth-dpop-key-priv";
210	const OAUTH_ACCESS_TOKEN_ACCOUNT: &str = "oauth-access-token";
211	const OAUTH_REFRESH_TOKEN_ACCOUNT: &str = "oauth-refresh-token";
212	const PDS_URL_ACCOUNT: &str = "relay-base-url";
213	const APPEARANCE_ACCOUNT: &str = "appearance-preference";
214	
215	/// Store the DPoP private key scalar (32 bytes) in the Keychain.
216	pub fn store_dpop_key(private_bytes: &[u8]) -> Result<(), KeychainError> {
217	    store_item(DPOP_KEY_PRIV_ACCOUNT, private_bytes)
218	}
219	
220	/// Load the DPoP private key scalar from the Keychain.
221	///
222	/// Returns `None` if no key has been stored yet (first run).
223	/// The returned bytes are wrapped in `Zeroizing` to ensure they are cleared on drop.
224	pub fn load_dpop_key() -> Option<zeroize::Zeroizing<[u8; 32]>> {
225	    match get_item(DPOP_KEY_PRIV_ACCOUNT) {
226	        Ok(bytes) if bytes.len() == 32 => {
227	            let mut arr = [0u8; 32];
228	            arr.copy_from_slice(&bytes);
229	            Some(zeroize::Zeroizing::new(arr))
230	        }
231	        Ok(_) => {
232	            tracing::warn!("DPoP key in Keychain has unexpected length; treating as absent");
233	            None
234	        }
235	        Err(e) if is_not_found(&e) => None,
236	        Err(e) => {
237	            tracing::error!(error = ?e, "Keychain error loading DPoP key");
238	            None
239	        }
240	    }
241	}
242	
243	/// Store the OAuth access token and refresh token in the Keychain.
244	pub fn store_oauth_tokens(access_token: &str, refresh_token: &str) -> Result<(), KeychainError> {
245	    store_item(OAUTH_ACCESS_TOKEN_ACCOUNT, access_token.as_bytes())?;
246	    store_item(OAUTH_REFRESH_TOKEN_ACCOUNT, refresh_token.as_bytes())?;
247	    Ok(())
248	}
249	
250	/// Load the OAuth access token and refresh token from the Keychain.
251	///
252	/// Returns `None` if either token is missing (not yet authenticated).
253	pub fn load_oauth_tokens() -> Option<(String, String)> {
254	    let access = match get_item(OAUTH_ACCESS_TOKEN_ACCOUNT) {
255	        Ok(b) => match String::from_utf8(b) {
256	            Ok(s) => s,
257	            Err(e) => {
258	                tracing::error!(error = ?e, "UTF-8 error decoding access token from Keychain");
259	                return None;
260	            }
261	        },
262	        Err(e) if is_not_found(&e) => return None,
263	        Err(e) => {
264	            tracing::error!(error = ?e, "Keychain error loading access token");
265	            return None;
266	        }
267	    };
268	    let refresh = match get_item(OAUTH_REFRESH_TOKEN_ACCOUNT) {
269	        Ok(b) => match String::from_utf8(b) {
270	            Ok(s) => s,
271	            Err(e) => {
272	                tracing::error!(error = ?e, "UTF-8 error decoding refresh token from Keychain");
273	                return None;
274	            }
275	        },
276	        Err(e) if is_not_found(&e) => return None,
277	        Err(e) => {
278	            tracing::error!(error = ?e, "Keychain error loading refresh token");
279	            return None;
280	        }
281	    };
282	    Some((access, refresh))
283	}
284	
285	/// Persist the user-configured PDS base URL to the Keychain.
286	///
287	/// Overwrites any previously stored URL.
288	pub fn store_pds_url(url: &str) -> Result<(), KeychainError> {
289	    store_item(PDS_URL_ACCOUNT, url.as_bytes())
290	}
291	
292	/// Retrieve the user-configured PDS base URL from the Keychain.
293	///
294	/// Returns `None` if no URL has been saved yet (first run or after logout).
295	pub fn load_pds_url() -> Option<String> {
296	    match get_item(PDS_URL_ACCOUNT) {
297	        Ok(bytes) => String::from_utf8(bytes)
298	            .map_err(|e| {
299	                tracing::error!(error = ?e, "PDS URL in Keychain is not valid UTF-8; treating as absent");
300	            })
301	            .ok(),
302	        Err(e) if is_not_found(&e) => None,
303	        Err(e) => {
304	            tracing::error!(error = ?e, "Keychain error loading PDS URL");
305	            None
306	        }
307	    }
308	}
309	
310	/// Remove the PDS URL from the Keychain. Test-only; used to reset state
311	/// between tests that share the Keychain mock store.
312	#[cfg(test)]
313	pub fn delete_pds_url_test_only() {
314	    let _ = delete_item(PDS_URL_ACCOUNT);
315	}
316	
317	/// Persist the in-app appearance preference (`"system"`, `"light"`, or `"dark"`).
318	///
319	/// The Keychain is the durable source of truth; the frontend keeps a
320	/// localStorage mirror purely so the preference can apply before first paint
321	/// (an async IPC read would land after the WebView has already painted).
322	pub fn store_appearance_preference(preference: &str) -> Result<(), KeychainError> {
323	    store_item(APPEARANCE_ACCOUNT, preference.as_bytes())
324	}
325	
326	/// Retrieve the stored appearance preference.
327	///
328	/// Returns `None` if no preference has been saved yet (follow the system).
329	pub fn load_appearance_preference() -> Option<String> {
330	    match get_item(APPEARANCE_ACCOUNT) {
331	        Ok(bytes) => String::from_utf8(bytes)
332	            .map_err(|e| {
333	                tracing::error!(error = ?e, "appearance preference in Keychain is not valid UTF-8; treating as absent");
334	            })
335	            .ok(),
336	        Err(e) if is_not_found(&e) => None,
337	        Err(e) => {
338	            tracing::error!(error = ?e, "Keychain error loading appearance preference");
339	            None
340	        }
341	    }
342	}
343	
344	/// Remove the appearance preference from the Keychain. Test-only; used to
345	/// reset state between tests that share the Keychain mock store.
346	#[cfg(test)]
347	pub fn delete_appearance_preference_test_only() {
348	    let _ = delete_item(APPEARANCE_ACCOUNT);
349	}
350	
351	/// Reset the in-memory Keychain to a clean state.
352	///
353	/// Call this at the start of every test that touches the Keychain so that
354	/// sequential tests sharing the same OS thread start with an empty store.
355	#[cfg(test)]
356	pub fn clear_for_test() {
357	    test_store::clear_all();
358	}
359	
360	/// In-memory Keychain substitute used exclusively in test builds.
361	///
362	/// Thread-local storage ensures tests on different threads are fully isolated.
363	/// Call `clear_for_test()` at the start of each test to handle sequential
364	/// reuse of the same OS thread by the Rust test harness.
365	///
366	/// Keys are `(scope, account)`, mirroring the real Keychain's two-store split: the same
367	/// account in `Local` and `Synced` is two independent records, and neither accessor family
368	/// can see the other's value. Tests that assert the launch backfill depend on that.
369	#[cfg(test)]
370	mod test_store {
371	    use std::cell::RefCell;
372	    use std::collections::HashMap;
373	
374	    /// Which of the two Keychain stores a call addresses.
375	    #[derive(Clone, Copy, PartialEq, Eq, Hash, Debug)]
376	    pub enum Scope {
377	        /// The default, device-local store.
378	        Local,
379	        /// The `kSecAttrSynchronizable` (iCloud Keychain) store.
380	        Synced,
381	    }
382	
383	    thread_local! {
384	        static STORE: RefCell<HashMap<(Scope, String), Vec<u8>>> = RefCell::new(HashMap::new());
385	    }
386	
387	    pub fn get(scope: Scope, account: &str) -> Option<Vec<u8>> {
388	        STORE.with(|s| s.borrow().get(&(scope, account.to_string())).cloned())
389	    }
390	
391	    pub fn set(scope: Scope, account: &str, data: Vec<u8>) {
392	        STORE.with(|s| {
393	            s.borrow_mut().insert((scope, account.to_string()), data);
394	        });
395	    }
396	
397	    pub fn delete(scope: Scope, account: &str) {
398	        STORE.with(|s| {
399	            s.borrow_mut().remove(&(scope, account.to_string()));
400	        });
401	    }
402	
403	    pub fn clear_all() {
404	        STORE.with(|s| s.borrow_mut().clear());
405	    }
406	}
407	
408	#[cfg(test)]
409	mod tests {
410	    use super::*;
411	
412	    const DID: &str = "did:plc:REDACTED";
413	
414	    /// The allowlist admits exactly the per-DID Share 1 slot — not the bare prefix, and not
415	    /// the deprecated app-global `recovery-share-1` account (a pre-unification install's
416	    /// Share 1 is read from there but never written back into iCloud under that name).
417	    #[test]
418	    fn only_per_did_share1_syncs() {
419	        assert!(syncs_to_icloud(&crate::rekey::recovery_share1_account(DID)));
420	        assert!(!syncs_to_icloud("recovery-share-1"));
421	        assert!(!syncs_to_icloud("recovery-share-1:"));
422	    }
423	
424	    /// Every secret the design keeps device-local must stay off the synchronizable store.
425	    /// Adding an account here without a design decision is the failure this guards.
426	    #[test]
427	    fn deny_list_accounts_never_sync() {
428	        let denied = [
429	            // Device key — Secure Enclave on device; `rotationKeys[0]`.
430	            "device-rotation-key-priv",
431	            "device-rotation-key-pub",
432	            "device-rotation-key-app-label",
433	            &format!("{DID}:device-key"),
434	            &format!("{DID}:device-key-pub"),
435	            &format!("{DID}:device-key-app-label"),
436	            // Live per-device credentials and the repo signing key.
437	            &format!("{DID}:oauth-tokens"),
438	            &format!("{DID}:recovery-signing-key"),
439	            // In-flight ceremony records — these hold reconstructable seed material.
440	            crate::share_ceremony::STAGING_ACCOUNT,
441	            crate::share_recovery::EPILOGUE_ACCOUNT,
442	            // Everything else the wallet stores, for completeness.
443	            "oauth-dpop-key-priv",
444	            "oauth-access-token",
445	            "oauth-refresh-token",
446	            "session-token",
447	            "device-token",
448	            "did",
449	            "managed-dids",
450	            "pending-removals",
451	            "relay-base-url",
452	            "appearance-preference",
453	            &format!("{DID}:did-doc"),
454	            &format!("{DID}:plc-log"),
455	        ];
456	        for account in denied {
457	            assert!(
458	                !syncs_to_icloud(account),
459	                "{account} must never be written to the iCloud-synchronizable keychain"
460	            );
461	            assert!(
462	                matches!(
463	                    store_item_synced(account, b"x"),
464	                    Err(KeychainError::SyncNotPermitted { .. })
465	                ),
466	                "{account} must be refused by the synchronizable write path"
467	            );
468	            assert!(matches!(
469	                get_item_synced(account),
470	                Err(KeychainError::SyncNotPermitted { .. })
471	            ));
472	            assert!(matches!(
473	                delete_item_synced(account),
474	                Err(KeychainError::SyncNotPermitted { .. })
475	            ));
476	        }
477	    }
478	
479	    /// A refused sync call is not an "item absent" verdict — a caller must not mistake it
480	    /// for one and conclude the share was never stored.
481	    #[test]
482	    fn sync_not_permitted_is_not_not_found() {
483	        assert!(!is_not_found(&KeychainError::SyncNotPermitted {
484	            account: "device-rotation-key-priv".to_string(),
485	        }));
486	    }
487	
488	    /// The two stores are independent records under one account name — the property the
489	    /// copy-never-flip backfill and the synced-first read path both rest on.
490	    #[test]
491	    fn synced_and_local_slots_are_distinct_records() {
492	        clear_for_test();
493	        let account = crate::rekey::recovery_share1_account(DID);
494	
495	        store_item(&account, b"LEGACY").unwrap();
496	        assert!(get_item_synced(&account).is_err_and(|e| is_not_found(&e)));
497	
498	        store_item_synced(&account, b"SYNCED").unwrap();
499	        assert_eq!(get_item(&account).unwrap(), b"LEGACY");
500	        assert_eq!(get_item_synced(&account).unwrap(), b"SYNCED");
501	
502	        // Deleting one store leaves the other intact.
503	        delete_item_synced(&account).unwrap();
504	        assert_eq!(get_item(&account).unwrap(), b"LEGACY");
505	    }
506	}
